mapper.select:



        AND l.agent_code = #{agentCode}


        AND l.status = #{status}


        AND l.biz_type = #{bizType}


        AND l.biz_id = #{bizId}


        AND l.fallback_used = #{fallbackUsed}


        AND l.create_time >= cast(#{params.beginTime} as date)


        AND l.create_time < cast(#{params.endTime} as date) + interval '1 day'


order by l.call_id desc
